for _,row in ipairs(rows) do for i,locale in ipairs(locales) do E.translations[locale][row[1]]=row[i] end end
local prose={
    ["Other bars help"]={
        "1–4 additional bars below you and your pet. Your pet does not count toward the limit. Build-up: a threat amount. After a second actor contributes: bars fill toward taking aggro, without numbers. Green/red borders mark the actual holder. Unknown range warns conservatively.",
        "1–4 weitere Balken unter dir und deinem Pet. Dein Pet zählt nicht mit. Aufbau: Bedrohungswert. Sobald ein zweiter Akteur beiträgt: Füllung bis zur Aggroübernahme, ohne Zahlen. Grün/rot umrahmt ist der tatsächliche Halter. Bei unbekannter Reichweite wird vorsichtig früher gewarnt.",
        "1–4 barres sous vous et votre familier, qui ne compte pas dans la limite. Montée : montant de menace. Dès qu’un second acteur intervient : proximité de prise d’aggro, sans chiffres. Le contour vert/rouge indique le détenteur. Portée inconnue : alerte anticipée.",
        "1–4 barras debajo de ti y tu mascota, que no cuenta para el límite. Acumulación: amenaza. Tras intervenir otro actor: proximidad de aggro, sin cifras. Borde verde/rojo para quien tiene aggro. Alcance desconocido: aviso temprano.",
        "1–4 barras abaixo de você e seu ajudante, que não conta no limite. Acúmulo: ameaça. Após outro participante: proximidade de aggro, sem números. Borda verde/vermelha marca quem tem aggro. Alcance desconhecido: aviso antecipado.",
        "1–4 полосы под вами и питомцем; питомец не учитывается в лимите. Набор: число угрозы. После второго участника: близость получения агро без чисел. Зелёная/красная рамка обозначает владельца. Неизвестная дистанция: раннее предупреждение.",
        "자신과 소환수 아래에 추가 막대 1–4개를 표시합니다. 자신의 소환수는 제한에 포함하지 않습니다. 축적 중에는 위협 수치, 두 번째 참여자부터는 어그로 획득까지의 진행도를 표시합니다. 테두리는 현재 대상을 나타냅니다. 거리 불명 시 일찍 경고합니다.",
        "在自己和宠物下方显示1–4条额外仇恨条，自身宠物不计入数量。建立阶段显示数值；第二个参与者加入后显示距离获得仇恨的进度，不显示数字。绿框或红框标记当前目标。距离未知时提前警告。"},
    ["Player color mode help"]={"Your own bar also keeps your player color, including build-up and fleeing. Other players and pets always use fixed colors. Pets get a distinct shade; customize it under Player colors. Green/red borders still identify the aggro holder."},
    ["Spell tooltip help"]={
        "Adds estimated threat to spellbook and action-bar tooltips. Damage, effective healing and fixed amounts are distinguished. Uses current talents and buffs. Unsupported abilities show no invented value; this is not a prediction of your next hit.",
        "Ergänzt geschätzte Bedrohung im Zauberbuch und an Aktionsleisten. Schaden, effektive Heilung und feste Beträge werden getrennt. Aktuelle Talente und Buffs zählen mit. Für unbekannte Fähigkeiten wird kein Wert erfunden; dies ist keine Vorhersage deines nächsten Treffers.",
        "Ajoute une estimation aux sorts du grimoire et des barres d’action. Dégâts, soins effectifs et montants fixes sont distingués, avec les talents et buffs actuels. Aucune valeur inventée pour les capacités inconnues ; ce n’est pas une prédiction du prochain coup.",
        "Añade amenaza estimada al libro de hechizos y barras de acción. Distingue daño, sanación efectiva y valores fijos con talentos y beneficios actuales. Sin cifras inventadas para habilidades desconocidas; no predice el siguiente golpe.",
        "Adiciona ameaça estimada ao livro e barras de ação. Distingue dano, cura efetiva e valores fixos com talentos e bônus atuais. Sem valores inventados para habilidades desconhecidas; não prevê o próximo golpe.",
        "Добавляет оценку угрозы в книгу заклинаний и панели действий. Учитывает урон, эффективное исцеление, фиксированные суммы, текущие таланты и эффекты. Не придумывает значения неизвестных способностей и не предсказывает следующий удар.",
        "마법책과 행동 단축바 툴팁에 위협 추정치를 추가합니다. 현재 특성과 강화 효과를 반영하여 피해, 유효 치유, 고정 위협을 구분합니다. 알 수 없는 기술의 값을 만들거나 다음 적중을 예측하지 않습니다.",
        "在法术书和动作条提示中添加仇恨估算。区分伤害、有效治疗和固定数值，并考虑当前天赋及增益。不为未知技能编造数值，也不预测下一次命中。"},
    ["SuperWoW transport help"]={"SuperWoW supplies extra client data; group messages still use the game's transport.","SuperWoW liefert zusätzliche Clientdaten; Gruppennachrichten verwenden weiterhin den Übertragungsweg des Spiels.","SuperWoW fournit des données supplémentaires ; les messages utilisent toujours le réseau du jeu.","SuperWoW aporta datos adicionales; los mensajes usan el transporte del juego.","SuperWoW fornece dados extras; as mensagens usam a rede do jogo.","SuperWoW даёт дополнительные данные; сообщения идут через сеть игры.","SuperWoW는 추가 데이터를 제공하지만 그룹 메시지는 게임 통신을 사용합니다.","SuperWoW提供额外数据，队伍消息仍通过游戏传输。"},
    ["Conservative range help"]={"Melee range is unknown for some actors. EasyThreat warns early at 110%; it does not assume everyone is ranged.","Bei einigen Akteuren ist die Nahkampfreichweite unbekannt. EasyThreat warnt vorsichtig ab 110 % und nimmt nicht pauschal Fernkampf an.","Portée de mêlée inconnue pour certains acteurs. Alerte prudente à 110 %, sans supposer le combat à distance.","Alcance cuerpo a cuerpo desconocido para algunos actores. Aviso prudente al 110 %, sin asumir distancia.","Alcance corpo a corpo desconhecido para alguns. Aviso prudente em 110 %, sem presumir combate à distância.","Дистанция ближнего боя известна не всем. Осторожное предупреждение при 110 %, без допущения дальнего боя.","일부 대상의 근접 거리를 알 수 없습니다. 모두 원거리로 가정하지 않고 110% 기준으로 일찍 경고합니다.","部分角色的近战距离未知，因此按110%提前警告，不假定所有人都在远程位置。"},
    ["Threat reply delayed help"]={"Threat replies take over 1.2 s including queue time. Record a session on both clients to distinguish transport delay from missing events.","Threat-Antworten brauchen einschließlich Warteschlange über 1,2 s. Auf beiden Clients eine Sitzung aufzeichnen, um Übertragungsverzögerung und fehlende Ereignisse zu unterscheiden.","Réponse de menace supérieure à 1,2 s, attente incluse. Enregistrez sur les deux clients pour distinguer retard réseau et événements manquants.","Respuesta superior a 1,2 s, incluida la cola. Graba en ambos clientes para distinguir retrasos y eventos ausentes.","Resposta acima de 1,2 s, incluindo fila. Grave nos dois clientes para distinguir atraso e eventos ausentes.","Ответ дольше 1,2 с с учётом очереди. Запишите сессию на обоих клиентах для поиска задержек и пропущенных событий.","대기열을 포함한 응답이 1.2초 이상입니다. 두 클라이언트에서 기록하여 통신 지연과 이벤트 누락을 구분하세요.","包含排队时间的响应超过1.2秒。请在两个客户端录制，以区分传输延迟和事件缺失。"},
}
for key,values in pairs(prose) do
    for i,locale in ipairs(locales) do if values[i] then E.translations[locale][key]=values[i] end end
end
